<?php require 'config.php';require_role('admin');verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['approve'])){$s=$pdo->prepare("UPDATE restaurants SET approved=? WHERE id=?");$s->execute([(int)$_POST['approved'],(int)$_POST['approve']]);flash('Restaurant approval updated.');redirect('admin.php');}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['order_status'])){$valid=['Pending','Accepted','Preparing','On the way','Delivered','Cancelled'];if(in_array($_POST['status'],$valid,true)){$s=$pdo->prepare("UPDATE orders SET status=? WHERE id=?");$s->execute([$_POST['status'],(int)$_POST['order_status']]);}redirect('admin.php');}
$restaurants=$pdo->query("SELECT r.*,u.email FROM restaurants r JOIN users u ON u.id=r.user_id ORDER BY r.id DESC")->fetchAll();$orders=$pdo->query("SELECT o.*,r.name restaurant_name FROM orders o JOIN restaurants r ON r.id=o.restaurant_id ORDER BY o.id DESC LIMIT 100")->fetchAll();$stats=$pdo->query("SELECT (SELECT COUNT(*) FROM users WHERE role='customer') customers,(SELECT COUNT(*) FROM restaurants) restaurants,(SELECT COUNT(*) FROM orders) orders,(SELECT COALESCE(SUM(total),0) FROM orders WHERE status<>'Cancelled') sales")->fetch();
$pageTitle='Admin dashboard';include 'partials/header.php';?>
<h1>Admin dashboard</h1><div class="grid"><?php foreach(['Customers'=>$stats['customers'],'Restaurants'=>$stats['restaurants'],'Orders'=>$stats['orders'],'Order value'=>'৳'.number_format((float)$stats['sales'],2)] as $k=>$v):?><div class="card"><p class="muted"><?=e($k)?></p><h2><?=e($v)?></h2></div><?php endforeach;?></div>
<h2>Restaurant approvals</h2><div class="table-wrap"><table><tr><th>Restaurant</th><th>Owner email</th><th>Area</th><th>Status</th><th>Action</th></tr><?php foreach($restaurants as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['area'])?></td><td><?=$r['approved']?'Approved':'Pending'?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="approve" value="<?=$r['id']?>"><button class="btn-secondary" name="approved" value="<?=$r['approved']?0:1?>"><?=$r['approved']?'Disable':'Approve'?></button></form></td></tr><?php endforeach;?></table></div>
<h2>All orders</h2><div class="table-wrap"><table><tr><th>Order</th><th>Customer</th><th>Restaurant</th><th>Total</th><th>Status</th><th>Update</th></tr><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['customer_name'])?></td><td><?=e($o['restaurant_name'])?></td><td>৳<?=number_format((float)$o['total'],2)?></td><td><?=e($o['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="order_status" value="<?=$o['id']?>"><select name="status"><?php foreach(['Pending','Accepted','Preparing','On the way','Delivered','Cancelled'] as $st):?><option <?=$st===$o['status']?'selected':''?>><?=$st?></option><?php endforeach;?></select><button class="btn-secondary">Save</button></form></td></tr><?php endforeach;?></table></div>
<?php include 'partials/footer.php';?>
